def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    if not isinstance(value, datetime.time):
        raise TypeError("Expected a datetime.time instance")
    return value.isoformat()

def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    if not hasattr(self, "_keys") or self._keys is None:
        return []
    return list(self._keys.keys())

def unit_of_work(metadata=None, timeout=None):
    """
    This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.
    """
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # The first positional argument is expected to be a Session object
            if not args:
                raise ValueError(
                    "The decorated function must receive a Session as its first argument."
                )
            session = args[0]
            tx_opts = {}
            if metadata is not None:
                tx_opts["metadata"] = metadata
            if timeout is not None:
                tx_opts["timeout"] = timeout
            try:
                with session.begin_transaction(**tx_opts) as tx:
                    # Pass the transaction object as the first argument to the wrapped function
                    return func(tx, *args[1:], **kwargs)
            except Exception:
                # Let the exception propagate after the transaction has been rolled back by the context manager
                raise
        return wrapper

    return decorator

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(f"Key {key!r} not found")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are specified, return all values
    if not keys:
        return [value for _, value in self.iteritems()]

    # Get a list of (key, value) pairs to support indexed access
    items = list(self.iteritems())
    result = []

    for key in keys:
        # If the key is an integer, treat it as an index
        if isinstance(key, int):
            if -len(items) <= key < len(items):
                result.append(items[key][1])
            else:
                raise IndexError(f'index {key} out of range')
        else:
            # Otherwise treat it as a normal key lookup
            try:
                result.append(self[key])
            except KeyError:
                raise KeyError(f'key {key} not found')

    return result

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate and normalise mode
        if mode is not None:
            mode = mode.upper()
            if mode not in ("READ", "WRITE"):
                raise ValueError("mode must be 'READ' or 'WRITE'")

        # Build the BEGIN parameters dictionary
        params = {}
        if mode is not None:
            params["mode"] = mode
        if bookmarks:
            params["bookmarks"] = list(bookmarks)
        if metadata is not None:
            params["metadata"] = metadata
        if timeout is not None:
            params["timeout"] = timeout
        if db is not None:
            params["db"] = db
        if imp_user is not None:
            params["imp_user"] = imp_user

        # Apply dehydration hooks to the values in params
        if dehydration_hooks:
            def dehydrate_value(value):
                for typ, func in dehydration_hooks.items():
                    if isinstance(value, typ):
                        return func(value)
                return value

            def walk(item):
                if isinstance(item, dict):
                    return {k: walk(v) for k, v in item.items()}
                if isinstance(item, (list, tuple)):
                    return [walk(v) for v in item]
                return dehydrate_value(item)

            params = walk(params)

        # Append BEGIN message to the protocol's outgoing queue.
        # The Bolt protocol expects an array where the first element is
        # the op‑code for BEGIN (0x11) and the second is a map of the
        # parameters collected above.  We assume the class has a
        # ``_output`` attribute that holds messages waiting to be sent.
        self._output.append([0x11, params])

        # If the class has a mechanism to wake the I/O loop, invoke it.
        if hasattr(self, "_wakeup"):
            self._wakeup()

        # Create and return a Response instance.  The Response constructor
        # is expected to accept a mapping of handlers that may be used
        # to process events for this transaction.
        return Response(**handlers)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            num = ''
            for c in part:
                if c.isdigit():
                    num += c
                else:
                    break
            nums.append(int(num) if num else 0)
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize < 0:
        raise ValueError('maxsize must be non-negative')
    def decorator(func):
        cache = collections.OrderedDict()
        def make_key(*args, **kwargs):
            if kwargs:
                kw_items = tuple(sorted(kwargs.items()))
            else:
                kw_items = ()
            if typed:
                # include types in key to differentiate values of same value but different types
                type_args = tuple(type(v) for v in args)
                type_kws = tuple(type(v) for k, v in kw_items)
                key = (*args, kw_items, type_args, type_kws)
            else:
                key = (*args, kw_items)
            return key
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(*args, **kwargs)
            now = timer()
            if key in cache:
                result, stamp = cache[key]
                if now - stamp <= ttl:
                    cache.move_to_end(key)
                    return result
                # expired
                del cache[key]
            result = func(*args, **kwargs)
            if maxsize and len(cache) >= maxsize:
                cache.popitem(last=False)
            cache[key] = (result, now)
            return result
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Most Recently Used (MRU) algorithm."""
    def decorator(fn):
        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            key = args
            if kwargs:
                key = key + tuple(sorted(kwargs.items()))
            if typed:
                key = key + tuple(type(v) for v in args)
                if kwargs:
                    key = key + tuple(type(v) for _, v in sorted(kwargs.items()))
            if key in cache:
                order.remove(key)
                order.insert(0, key)
                return cache[key]
            result = fn(*args, **kwargs)
            cache[key] = result
            order.insert(0, key)
            if len(order) > maxsize:
                evict_key = order.pop()
                cache.pop(evict_key, None)
            return result

        wrapper.cache = cache
        wrapper.order = order
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(fn):
        if maxsize <= 0:
            @wraps(fn)
            def no_cache(*args, **kwargs):
                return fn(*args, **kwargs)
            no_cache.cache = {}
            no_cache.cache_clear = no_cache.cache.pop
            no_cache.cache_info = lambda: None
            return no_cache

        cache = {}
        order = OrderedDict()

        def make_key(args, kwargs):
            key = args
            if kwargs:
                # Use frozenset of items to make order-insensitive key
                key += (tuple(sorted(kwargs.items())),)
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        @wraps(fn)
        def wrapped(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # Move to end to mark as recently used
                order.move_to_end(key)
                return cache[key]
            # Compute the result
            result = fn(*args, **kwargs)
            if len(cache) >= maxsize:
                # Pop the first (least recently used) item
                old_key, _ = order.popitem(last=False)
                cache.pop(old_key, None)
            cache[key] = result
            order[key] = None
            return result

        # expose cache attributes
        wrapped.cache = cache
        wrapped.cache_clear = lambda: (_ for _ in ()).throw(NotImplementedError)  # placeholder
        wrapped.cache_info = lambda: None
        return wrapped

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            # Create cache key
            if typed:
                key = args + tuple(sorted(kwargs.items()))
                key = (key,
                       tuple(type(arg) for arg in args),
                       tuple((k, type(kwargs[k])) for k in sorted(kwargs)))
            else:
                key = args + tuple(sorted(kwargs.items()))
            if key in cache:
                value, count = cache[key]
                cache[key] = (value, count + 1)
                return value
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Find and remove the least frequently used item
                min_count = min(v[1] for v in cache.values())
                for k in list(cache):
                    if cache[k][1] == min_count:
                        del cache[k]
                        break
            cache[key] = (result, 1)
            return result
        return wrapper
    return decorator

