def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    clsname = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if clsname.endswith(suffix):
            clsname = clsname[:-len(suffix)]
    return clsname

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Build adjacency list and indegree counts
    adjacency = {}
    indegree = {}
    for ordering in orderings:
        for idx, node in enumerate(ordering):
            if node not in adjacency:
                adjacency[node] = set()
            if node not in indegree:
                indegree[node] = 0
            if idx < len(ordering) - 1:
                nxt = ordering[idx + 1]
                if nxt not in adjacency:
                    adjacency[nxt] = set()
                if nxt not in indegree:
                    indegree[nxt] = 0
                if nod not in adjacency[node]:
                    adjacency[node].add(nxt)
                    indegree[nxt] += 1

    # Determine earliest occurrence (index, order_index) for each node
    first_occurrence = {}
    for order_idx, ordering in enumerate(orderings):
        for idx, node in enumerate(ordering):
            key = (idx, order_idx)
            if node not in first_occurrence or key < first_occurrence[node]:
                first_occurrence[node] = key

    # Kahn's algorithm with priority based on earliest occurrence
    result = []
    processed = set()
    zero_set = {node for node, deg in indegree.items() if deg == 0}

    while zero_set:
        # select node with smallest (index, order_idx)
        node = min(zero_set, key=lambda n: first_occurrence[n])
        zero_set.remove(node)
        result.append(node)
        processed.add(node)
        for nbr in adjacency.get(node, ()):
            indegree[nbr] -= 1
            if indegree[nbr] == 0:
                zero_set.add(nbr)

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Collect the classes that are not superclasses of any other class
    # in the original list.
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            continue
        # A class is redundant if any other class in the list is a subclass of it.
        redundant = False
        for other in classes:
            if other is cls or not isinstance(other, type):
                continue
            if issubclass(other, cls):
                redundant = True
                break
        if not redundant:
            result.append(cls)
    return result

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # If all is True, return all instance attributes that have docstrings.
    if all:
        result = {}
        for name, value in vars(self).items():
            desc = getattr(value, "__doc__", "")
            if desc is None:
                desc = ""
            result[name] = desc
        return result

    # Prefer an explicit interface mapping if defined.
    interface = getattr(self.__class__, "_interface", None)
    if interface is None:
        interface = getattr(self, "_interface", None)

    if isinstance(interface, dict):
        # Return only those keys present in the interface mapping.
        return {name: interface.get(name, "") for name in interface}

    # Fallback: return all instance attributes with available docstrings.
    result = {}
    for name, value in vars(self).items():
        desc = getattr(value, "__doc__", "")
        if desc is None:
            desc = ""
        result[name] = desc
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect attribute names from the class hierarchy
    attr_set = set()
    for cls in type(self).__mro__:
        for name, value in vars(cls).items():
            if name.startswith('_'):
                continue
            if not all and callable(value):
                continue
            attr_set.add(name)
    # Add instance-specific attributes
    for name, value in vars(self).items():
        if name.startswith('_'):
            continue
        if not all and callable(value):
            continue
        attr_set.add(name)
    return sorted(attr_set)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, "__bases__", ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        import importlib
        return importlib.import_module("c_optimizations")
    except ImportError:
        return False

def _c_optimizations_ignored(self):
    """The opposite of `_c_optimizations_required`."""
    pass

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    self.context = {}

    # Reinitialize bins
    # If an initial_value is defined, use it to fill existing bins
    if hasattr(self, "initial_value"):
        if hasattr(self, "bins") and self.bins is not None:
            self.bins = [self.initial_value for _ in self.bins]
        elif hasattr(self, "counts") and self.counts is not None:
            self.counts = [self.initial_value for _ in self.counts]
    # Otherwise try to create new bins using a make_bins method
    elif callable(getattr(self, "make_bins", None)):
        self.bins = self.make_bins()
    # If neither is available, clear any existing bin-like structures
    else:
        if hasattr(self, "bins"):
            self.bins = []
        if hasattr(self, "counts"):
            self.counts = []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have error index information")
    try:
        return self._err_indices[coord_name]
    except KeyError:
        raise KeyError(f"Coordinate {coord_name!r} not found in error indices")

def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct FillRequest instance is always allowed
    if isinstance(seq, FillRequest):
        return True

    # Exclude Source sequences explicitly
    if isinstance(seq, Source):
        return False

    # Strings and bytes should not be treated as sequences for this purpose
    if isinstance(seq, (str, bytes)):
        return False

    # Try to iterate over seq and look for a FillRequest element
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        return False

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    for name in ('fill', 'compute'):
        attr = getattr(obj, name, None)
        if not callable(attr):
            return False
    return True

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and *d2*
    but has different values, it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if level == 0:
        return {}
    result = {}
    for key, val in d1.items():
        if key not in d2:
            # key missing in d2: copy the value
            result[key] = val
        else:
            other = d2[key]
            if val == other:
                continue
            # values differ
            if level > 1 and isinstance(val, dict) and isinstance(other, dict):
                # recurse into nested dicts
                sublevel = level - 1 if level > 0 else -1
                subdiff = difference(val, other, sublevel)
                if subdiff:
                    result[key] = subdiff
            else:
                # include differing value
                result[key] = val
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`,
    this function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """
    for field in observer_schema:
        # A simple field name
        if isinstance(field, (str, int, float, bool)):
            key = field
            if key not in last_applied_manifest and key in response:
                # Preserve complex structures from response if present
                last_applied_manifest[key] = response[key]
            continue

        # If field is a mapping, it represents nested schema
        if isinstance(field, dict):
            for sub_key, sub_schema in field.items():
                # Ensure we have a container for the nested field
                if sub_key not in last_applied_manifest:
                    # Start an empty dict; details are handled by the helper
                    last_applied_manifest[sub_key] = {}
                # Recursively apply dictionary update
                if sub_key in response:
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[sub_key], sub_schema, response[sub_key]
                    )
            continue

        # If field is a sequence of subfields (e.g., list of dicts)
        if isinstance(field, list):
            # Handle each subfield in sequence
            for subfield in field:
                # Treat each subfield similarly
                if isinstance(subfield, dict):
                    for sub_key, sub_schema in subfield.items():
                        if sub_key not in last_applied_manifest:
                            last_applied_manifest[sub_key] = {}
                        if sub_key in response:
                            update_last_applied_manifest_dict_from_resp(
                                last_applied_manifest[sub_key], sub_schema, response[sub_key]
                            )
                else:
                    key = subfield
                    if key not in last_applied_manifest and key in response:
                        last_applied_manifest[key] = response[key]
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Existing default observer schema dict; create if missing
    if not hasattr(app.spec, "default_observer_schema"):
        app.spec.default_observer_schema = {}
    default_schemas = app.spec.default_observer_schema

    # Existing custom observer schema dict; create if missing
    if not hasattr(app.spec, "custom_observer_schema"):
        app.spec.custom_observer_schema = {}
    custom_schemas = app.spec.custom_observer_schema

    # Iterate over resources in the manifest
    for resource in getattr(app.spec, "manifest", []):
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue

        # Skip if a custom schema is already defined for this kind
        if kind in custom_schemas:
            continue

        # Build a minimal default schema that includes the essential API
        # attributes and an empty spec to allow any fields.
        api_version = resource.get("apiVersion", "")
        default_schemas[kind] = {
            "apiVersion": api_version,
            "kind": kind,
            "metadata": {
                "name": {"type": "string"},
                "namespace": {"type": "string"},
                "labels": {"type": "object"},
                "annotations": {"type": "object"},
            },
            "spec": {},
        }

    # Assign the updated map back to the application spec
    app.spec.default_observer_schema = default_schemas
    return None

def status_str(self, prefix=''):
        """Return string of validator status, with optional prefix."""
        try:
            status_msg = self._STATUS2STR[self.status]
        except Exception:
            status_msg = str(self.status)
        return f"{prefix}{status_msg}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    log_entries = getattr(self, 'log', [])
    if not isinstance(log_entries, (list, tuple)):
        return prefix + str(log_entries)
    return "\n".join(f"{prefix}{entry}" for entry in log_entries)

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Determine the spec version to validate against.
        spec_version = self.spec_version

        if extract_spec_version:
            type_value = inventory.get('type')
            if type_value:
                # Map known type strings to internal spec version identifiers.
                type_to_version = {
                    'inventory_v1': 'v1',
                    'inventory_v2': 'v2',
                }
                if type_value in type_to_version:
                    spec_version = type_to_version[type_value]
                else:
                    raise ValueError(
                        f"Unknown inventory type '{type_value}'. "
                        f"Expected one of {list(type_to_version.keys())}."
                    )
            # If no type field, fall back to the default spec_version.

        # Define basic schema expectations per version.
        if spec_version == 'v2':
            required_keys = {'id', 'name', 'items'}
            optional_keys = {'type', 'metadata'}
        else:  # assume 'v1'
            required_keys = {'id', 'items'}
            optional_keys = {'type'}

        # Validate presence of required keys.
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(
                f"Inventory missing required keys for spec version '{spec_version}': "
                f"{', '.join(sorted(missing))}"
            )

        # Ensure there are no unexpected keys.
        unexpected = inventory.keys() - required_keys - optional_keys
        if unexpected:
            raise ValueError(
                f"Inventory contains unexpected keys for spec version '{spec_version}': "
                f"{', '.join(sorted(unexpected))}"
            )

        # Validate contents of the 'items' field if present.
        items = inventory.get('items')
        if items is None:
            # Items is mandatory but None is considered missing.
            raise ValueError(f"'items' field is required and cannot be None for spec version '{spec_version}'.")
        if not isinstance(items, list):
            raise ValueError(
                f"'items' must be a list. Got {type(items).__name__}."
            )
        # Each item in the list must be a dict (a simple sanity check).
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                raise ValueError(
                    f"Item at index {idx} in 'items' must be a dict. "
                    f"Got {type(item).__name__}."
                )

        # If all checks pass, return the inventory unchanged.
        return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalize input
    if manifest_files is None:
        raise ValueError("manifest_files must not be None")
    if digests_used is None:
        raise ValueError("digests_used must not be None")

    # The manifest could be a mapping from digest to filename or a list of such mappings.
    # Build a set of digests that are actually present in the manifest.
    present_digests = set()
    if isinstance(manifest_files, dict):
        # assume key is digest
        present_digests.update(manifest_files.keys())
    elif hasattr(manifest_files, "__iter__"):
        for entry in manifest_files:
            if isinstance(entry, dict):
                # try to find a key named 'digest'
                if "digest" in entry:
                    present_digests.add(entry["digest"])
                # or a tuple (digest, filename)
                elif len(entry) >= 1:
                    present_digests.add(entry[0])
            elif isinstance(entry, (list, tuple)):
                if entry:
                    present_digests.add(entry[0])
            else:
                # fall back to treating the entry itself as a digest
                present_digests.add(entry)
    else:
        raise TypeError("manifest_files must be a dict or iterable")

    # Convert digests_used to a set for fast lookup
    used_digests = set(digests_used)

    # Digests required by the manifest but missing from the known set
    missing = used_digests - present_digests
    # Digests present in the manifest that were never used
    unused = present_digests - used_digests

    if missing:
        raise RuntimeError("Missing digests in manifest: %s" % ", ".join(sorted(missing)))
    if unused:
        # It's not an error to have unused digests, but a warning is useful.
        try:
            self.logger.warning("Found digests in manifest that were not used: %s" % ", ".join(sorted(unused)))
        except AttributeError:
            # If no logger is defined, silently ignore
            pass
    # If everything is fine, just return None
    return None

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object."""
        # ensure prior is of the same type
        if not isinstance(prior, type(self)):
            raise TypeError(f"prior must be an instance of {type(self).__name__}, not {type(prior).__name__}")

        # check that both inventories expose a version attribute
        if not hasattr(self, "version") or not hasattr(prior, "version"):
            raise ValueError("Both inventories must have a 'version' attribute for comparison")

        # prior must be older than current inventory
        if prior.version >= self.version:
            raise ValueError(f"Prior inventory (version {prior.version}) is not older than current inventory (version {self.version})")

        # Compare species names
        if set(prior.species) != set(self.species):
            raise ValueError(
                f"Species mismatch between current and prior inventories:\n"
                f"current species: {sorted(self.species)}\n"
                f"prior species:   {sorted(prior.species)}"
            )

        # Compare parameters
        if set(prior.parameters) != set(self.parameters):
            raise ValueError(
                f"Parameters mismatch between current and prior inventories:\n"
                f"current parameters: {sorted(self.parameters)}\n"
                f"prior parameters:   {sorted(prior.parameters)}"
            )

        # Compare constraints keys (indices or parameter names)
        if set(prior.constraints.keys()) != set(self.constraints.keys()):
            raise ValueError(
                f"Constraint keys mismatch between current and prior inventories:\n"
                f"current: {sorted(self.constraints.keys())}\n"
                f"prior:   {sorted(prior.constraints.keys())}"
            )

        # Compare each constraint definition (e.g., bounds)
        for key in self.constraints:
            curr_range = self.constraints[key]
            prior_range = prior.constraints[key]
            if curr_range != prior_range:
                raise ValueError(
                    f"Constraint for '{key}' differs between inventories:\n"
                    f"current: {curr_range}\n"
                    f"prior:   {prior_range}"
                )

        # Compare transformation metadata if present
        if hasattr(self, "transformations") and hasattr(prior, "transformations"):
            if set(self.transformations.keys()) != set(prior.transformations.keys()):
                raise ValueError(
                    f"Transformation keys mismatch between current and prior inventories:\n"
                    f"current: {sorted(self.transformations.keys())}\n"
                    f"prior:   {sorted(prior.transformations.keys())}"
                )
            for key in self.transformations:
                curr_trans = self.transformations[key]
                prior_trans = prior.transformations[key]
                if curr_trans.__class__ != prior_trans.__class__:
                    raise ValueError(
                        f"Transformation type for '{key}' differs: "
                        f"{curr_trans.__class__.__name__} vs {prior_trans.__class__.__name__}"
                    )

        # Validate that inventory structure (e.g., stoichiometry matrix, propensity matrix) is identical
        if hasattr(self, "stoichiometry") and hasattr(prior, "stoichiometry"):
            if (self.stoichiometry.shape != prior.stoichiometry.shape or
                not np.allclose(self.stoichiometry, prior.stoichiometry)):
                raise ValueError("Stoichiometry matrices differ between inventories")

        if hasattr(self, "propensity_matrix") and hasattr(prior, "propensity_matrix"):
            if (self.propensity_matrix.shape != prior.propensity_matrix.shape or
                not np.allclose(self.propensity_matrix, prior.propensity_matrix)):
                raise ValueError("Propensity matrices differ between inventories")

        # If all checks pass, inventory is a valid prior version
        return None

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_map = {}

    # Case 1: inventory is a dict mapping version to a mapping of logical_path -> files
    if isinstance(inventory, dict):
        if version in inventory:
            mapping = inventory[version]
            if isinstance(mapping, dict):
                for lp, files in mapping.items():
                    if isinstance(files, (list, set, tuple)):
                        logical_map.setdefault(lp, set()).update(files)
                    else:
                        logical_map.setdefault(lp, set()).add(files)
            else:
                # Assume iterable of (logical_path, files) tuples
                for lp, files in mapping:
                    if isinstance(files, (list, set, tuple)):
                        logical_map.setdefault(lp, set()).update(files)
                    else:
                        logical_map.setdefault(lp, set()).add(files)

    # Case 2: inventory is an iterable of entry dicts with 'version', 'logical_path', 'content_file'
    else:
        for entry in inventory:
            if entry.get("version") == version:
                lp = entry.get("logical_path")
                if lp is None:
                    continue
                files = entry.get("content_file")
                if isinstance(files, (list, set, tuple)):
                    logical_map.setdefault(lp, set()).update(files)
                else:
                    logical_map.setdefault(lp, set()).add(files)

    return logical_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dict, got %r" %
                             type(fixity).__name__)
        if 'files' not in fixity:
            raise ValueError("Fixity block missing required 'files' key")
        files = fixity['files']
        if not isinstance(files, dict):
            raise ValueError("'files' entry must be a dict, got %r" %
                             type(files).__name__)

        # Convert the manifest list to a set for efficient lookup
        manifest_set = set(manifest_files)

        for fname, hash_dict in files.items():
            if fname not in manifest_set:
                raise ValueError("Fixity references unknown file '%s' not present in the manifest" % fname)
            if not isinstance(hash_dict, dict) or not hash_dict:
                raise ValueError("Hash data for file '%s' must be a non-empty dict" % fname)

        return True

def files_list(path):
    """
    Return the files in `path`
    """
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        return [os.path.abspath(os.path.join(path, f))
                for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f))]
    return []

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            hits = node.xpath(xpath)
            if hits:
                return hits[0]
        except Exception:
            # fallback: try simple CSS selector with BeautifulSoup
            try:
                hits = node.select(xpath)
                if hits:
                    return hits[0]
            except Exception:
                continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    cls_name = self.__class__.__name__
    attrs = getattr(self, "__dict__", {})
    if not attrs:
        return f"{indent_str}{cls_name}()"
    lines = [f"{indent_str}{cls_name} {{"]
    for key, value in attrs.items():
        prefix = f"{indent_str}  {key}="
        if hasattr(value, "pretty") and callable(value.pretty):
            val_str = value.pretty(indent + 2, debug)
        else:
            if debug:
                val_str = f"{type(value).__name__}({repr(value)})"
            else:
                val_str = repr(value)
        lines.append(prefix + val_str)
    lines.append(f"{indent_str}}}")
    return "\n".join(lines)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if PY3:
            return result
        else:
            return result.encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        with open(VERSION_PATH, 'r') as rfile:
            contents = rfile.read().strip()
        _, version = contents.split('=')
        return version.strip().strip('"\'')

    except Exception:
        return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Normalise pieces to a list of strings
    if pieces is None:
        pieces = []
    elif not isinstance(pieces, (list, tuple)):
        pieces = [pieces]
    pieces = [str(p) for p in pieces]

    if style == "plain":
        # Return a simple space‑separated string
        return " ".join(pieces)

    if style == "markdown":
        # Return a Markdown bullet list
        return "\n".join(f"- {p}" for p in pieces)

    if style == "html":
        # Wrap each piece in an <li> element inside a <ul>
        list_items = "\n".join(f"  <li>{p}</li>" for p in pieces)
        return f"<ul>\n{list_items}\n</ul>"

    if style == "json":
        # Return a JSON representation of the pieces
        import json
        return json.dumps(pieces)

    raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '+' if '+' not in pieces else '.'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)

    if verbose:
        print(f"Running command: {cmd}")

    # Set up subprocess parameters
    stderr_mode = subprocess.STDOUT if hide_stderr else subprocess.PIPE
    try:
        output = subprocess.check_output(
            cmd,
            cwd=cwd,
            env=env,
            stderr=stderr_mode,
            shell=False
        )
        return output.decode()
    except subprocess.CalledProcessError as e:
        # If hide_stderr, e.output will be None, otherwise it will contain stderr
        err_msg = f"Command '{cmd}' failed with return code {e.returncode}"
        if e.output:
            err_msg += f"\nOutput: {e.output.decode()}"
        raise RuntimeError(err_msg) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e

def register_vcs_handler(vcs, method):  # tyoe: (str, str) -> typing.Callable  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    # Expect the hierarchy to expose an iterable of objects; fallback to empty list if not present
    objects = getattr(self, 'objects', [])
    for obj in objects:
        num_objects += 1
        valid = True
        if validate_objects:
            try:
                obj.validate()
            except Exception:
                valid = False
        if check_digests:
            try:
                if not obj.digest_matches():
                    valid = False
            except AttributeError:
                if show_warnings:
                    obj_id = getattr(obj, 'id', str(obj))
                    print(f"WARNING: Object {obj_id} does not support digest check")
        if not valid:
            if show_warnings:
                obj_id = getattr(obj, 'id', str(obj))
                print(f"WARNING: Object {obj_id} failed validation")
        else:
            good_objects += 1
    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        return

    # Ensure the tracking dict exists
    if not hasattr(self, "changed_digests"):
        self.changed_digests = {}

    # The inventory files are expected to be named 'inventory.json' in each directory
    root_digest_map = {}
    seen_files = set()

    for idx, vdir in enumerate(version_dirs):
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory.json in {vdir!r}")

        with open(inv_path, "rt", encoding="utf-8") as fp:
            try:
                inv = json.load(fp)
            except ValueError as exc:
                raise ValueError(f"Invalid JSON in {inv_path!r}: {exc}") from exc

        files = inv.get("files", [])
        current_files = set()

        for entry in files:
            path = entry.get("path")
            digest = entry.get("digest")
            if path is None:
                raise ValueError(f"Entry in {inv_path!r} missing 'path' field")
            current_files.add(path)

            # Record digest mismatch against the root inventory (first version)
            if idx == 0:
                root_digest_map[path] = digest
            else:
                root_digest = root_digest_map.get(path)
                if root_digest is not None and root_digest != digest:
                    if path not in self.changed_digests:
                        self.changed_digests[path] = []
                    self.changed_digests[path].append(
                        {"version": vdir, "root_digest": root_digest, "current_digest": digest}
                    )

        # All files from previous versions must still be present
        missing = seen_files - current_files
        if missing:
            raise ValueError(
                f"Version {vdir!r} is missing files that existed in earlier versions: {sorted(missing)}"
            )

        seen_files.update(current_files)

    # If we reach here, the inventories are consistent
    return self.changed_digests?>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure bug_ids is a list or tuple.
    if isinstance(bug_ids, (list, tuple)):
        ids = bug_ids
    else:
        ids = [bug_ids]
    # Build a comma‑separated string of IDs.
    ids_str = ','.join(str(i) for i in ids)
    # Merge with any existing 'ids' parameter.
    if 'ids' in params:
        existing = params['ids']
        if isinstance(existing, (list, tuple)):
            existing_str = ','.join(str(i) for i in existing)
        else:
            existing_str = str(existing)
        params['ids'] = f"{existing_str},{ids_str}"
    else:
        params['ids'] = ids_str
    return params

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode key, Node value) tuples. Duplicate keys
    (identified by ScalarNode.value) are merged: if both values are mapping
    nodes, their contents are recursively merged; otherwise the later value
    wins. The function returns a new list with merged content.
    """
    # Helper to determine if a node is a MappingNode
    def _is_mapping(node):
        return hasattr(node, "value") and isinstance(node.value, list)

    # Recursively merge two mapping nodes
    def _merge_mapping_nodes(m1, m2):
        """
        Merge mapping node m2 into m1 in place and return m1.
        """
        mapping = {}
        # Populate with entries from m1
        for k, v in m1.value:
            mapping[k.value] = [k, v]
        # Merge entries from m2
        for k, v in m2.value:
            key = k.value
            if key in mapping:
                existing_val = mapping[key][1]
                if _is_mapping(existing_val) and _is_mapping(v):
                    _merge_mapping_nodes(existing_val, v)
                else:
                    mapping[key][1] = v
            else:
                mapping[key] = [k, v]
        # Reconstruct the ordered value list
        m1.value = [pair[1] for pair in mapping.values()]
        return m1

    result = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in result:
            result[key] = (key_node, value_node)
        else:
            _, existing_value = result[key]
            if _is_mapping(existing_value) and _is_mapping(value_node):
                merged = _merge_mapping_nodes(existing_value, value_node)
                result[key] = (key_node, merged)
            else:
                # last value wins
                result[key] = (key_node, value_node)

    # Preserve the order of first insertion
    return list(result.values())

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def _dictsum(dicts):
    """Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url or not url_args:
        return url

    def _replacement(match):
        key = match.group(1) or match.group(2)
        return str(url_args.get(key, match.group(0)))

    pattern = r'\{(\w+)\}|\:(\w+)'
    return re.sub(pattern, _replacement, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str) and val.strip().lower() == 'none':
        return True
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        flags.extend(action.option_strings)
    return ' '.join(flags)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    # Handle dictionaries
    if isinstance(flow_params, dict):
        # If the key to replace exists, rename it to the register number
        if register_value in flow_params:
            flow_params[register_number] = flow_params.pop(register_value)
        # Replace any values matching the key
        for key, val in list(flow_params.items()):
            if val == register_value:
                flow_params[key] = register_number
            elif isinstance(val, (dict, list)):
                _replace_register(val, register_number, register_value)
    # Handle lists recursively
    elif isinstance(flow_params, list):
        for idx, item in enumerate(flow_params):
            if item == register_value:
                flow_params[idx] = register_number
            elif isinstance(item, (dict, list)):
                _replace_register(item, register_number, register_value)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        value = str(value)
    if not isinstance(arg, str):
        arg = str(arg)
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])
    while queue:
        c = queue.pop()
        seen.add(c)
        for sub in c.__subclasses__():
            if sub not in seen:
                queue.add(sub)
    seen.discard(cls)
    return seen

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    return name.strip('\'"')

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT
        )
        files = output.decode().strip().splitlines()
        files.sort()
        return ','.join(files)
    except subprocess.CalledProcessError:
        return ''

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Quick string checks
    if host in ('localhost', '127.0.0.1', '::1'):
        return True

    try:
        addrs = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in addrs:
        ip = sockaddr[0]
        if family == socket.AF_INET and ip == '127.0.0.1':
            return True
        if family == socket.AF_INET6 and ip == '::1':
            return True

    return False

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if pattern is None:
        return None
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    if isinstance(pattern, re.Pattern):
        return pattern
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize inputs
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        args = [args]

    results = []

    for cmd in commands:
        full_cmd = [cmd] + list(args)
        if verbose:
            print(f"Running: {full_cmd}")
        # Determine stderr handling
        stderr = subprocess.DEVNULL if hide_stderr else None
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=stderr,
                text=True,
                check=True
            )
        except subprocess.CalledProcessError as e:
            raise subprocess.CalledProcessError(
                e.returncode, e.cmd,
                output=e.output, stderr=e.stderr
            ) from None
        results.append(result)

    return results

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        ipaddress.IPv4Address(target)
    except (ipaddress.AddressValueError, ValueError):
        return False
    return True

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is not None:
        return yaml.safe_dump(obj, default_flow_style=False, Dumper=dumper)
    return yaml.safe_dump(obj, default_flow_style=False)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
      - dict of configuration filename to corresponding parsed configuration,
      - sequence of logging.LogRecord instances containing any parse errors.
    '''
    results = {}
    error_records = []
    logger = logging.getLogger('config_loader')

    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                if filename.lower().endswith(('.yaml', '.yml')):
                    config = yaml.safe_load(fd)
                elif filename.lower().endswith('.json'):
                    config = json.load(fd)
                else:
                    config = {}
            if config is None:
                config = {}
            if overrides:
                config.update(overrides)
            if resolve_env:
                def _resolve(val):
                    if isinstance(val, dict):
                        return {k: _resolve(v) for k, v in val.items()}
                    if isinstance(val, list):
                        return [_resolve(v) for v in val]
                    if isinstance(val, str):
                        # simple ${VAR} substitution
                        import re
                        def repl(m):
                            return os.getenv(m.group(1), '')
                        return re.sub(r'\${([^}]+)}', repl, val)
                    return val
                config = _resolve(config)
            results[filename] = config
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=exc
            )
            error_records.append(record)
            continue

    return results, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, unicode_):
        return obj.encode('utf-8')
    else:
        return obj

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Convert each raw string into a Bookmark instance.  
    # If the Bookmark class provides a dedicated parsing method, use it;
    # otherwise fall back to the constructor.
    bookmarks = []
    for raw in values:
        if hasattr(Bookmark, "from_raw"):
            bookmark = Bookmark.from_raw(raw)
        else:
            bookmark = Bookmark(raw)
        bookmarks.append(bookmark)
    return cls(bookmarks)

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new value is provided
    if other is None:
        return getattr(self, "_scale", None)

    # Ensure the new scale is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("The scale factor must be a numeric value")

    # Current scale must be known and non‑zero
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale")

    # Determine the index of the last coordinate (assuming numeric columns are stored in `data`)
    if hasattr(self, "data") and isinstance(self.data, (list, tuple)):
        # Assume data is a 2‑D array-like structure
        try:
            last_idx = len(self.data[0]) - 1
        except Exception:
            last_idx = None
    else:
        last_idx = None

    # If we have a usable last index, rescale the data and associated errors
    if last_idx is not None:
        # Rescale the data column
        scaled_factor = other / current_scale
        # Use try/except so code remains robust if data format differs
        try:
            if hasattr(self, "data"):
                # If data is a numpy array or similar
                self.data[:, last_idx] *= scaled_factor
            if hasattr(self, "errors"):
                self.errors[:, last_idx] *= scaled_factor
        except Exception:
            # Fallback for list‑of‑lists representation
            if hasattr(self, "data"):
                for row in self.data:
                    row[last_idx] *= scaled_factor
            if hasattr(self, "errors"):
                for row in self.errors:
                    row[last_idx] *= scaled_factor

    # Update the stored scale and return the modified graph
    self._scale = other
    return self

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""

    # If an explicit metaclass is supplied, use it directly.
    if explicit_mc is not None:
        return explicit_mc

    if not bases:
        # No bases means the default metaclass is `type`.
        return type

    # Compute the implicit metaclass based on the bases.
    metaclasses = [type(b) for b in bases]
    chosen = metaclasses[0]
    for m in metaclasses[1:]:
        if issubclass(m, chosen):
            chosen = m
        elif not issubclass(chosen, m):
            raise TypeError(
                f"cannot combine metaclasses {chosen!r} "
                f"and {m!r} for bases {bases!r}"
            )

    return chosen

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map:
            return map.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._cache:
        raise KeyError('cache is empty')
    # Get a key from the bucket with the current minimum frequency
    key, _ = self._freq_keys[self._minfreq].popitem(last=False)
    value = self._cache.pop(key)
    # Remove key from frequency tracking
    del self._freq[key]
    # If the bucket is now empty, remove it and update the minimum frequency
    if not self._freq_keys[self._minfreq]:
        del self._freq_keys[self._minfreq]
        if self._freq_keys:
            self._minfreq = min(self._freq_keys)
        else:
            self._minfreq = 0
    return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self._cache:
        raise KeyError('LRU cache is empty')
    key, value = self._cache.popitem(last=False)
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('dict is empty')
    key, value = super().popitem()
    return key, value

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.
    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    converters = {}
    # Build a mapping from style keys to conversion callables.
    for style_key, style_value in getattr(self, "style_types", {}).items():
        # If the style value is already a callable, use it directly.
        if callable(style_value):
            conv = style_value
        # If the style value is a string, interpret it as a converter name.
        elif isinstance(style_value, str):
            conv = self._get_converter(style_value)
        else:
            # Fallback: no conversion.
            conv = None
        converters[style_key] = conv
    return _converting._Converter(converters)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Try public XML payload first
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    # Then try private JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Ensure dt is a datetime instance
    if not hasattr(dt, "strftime"):
        raise TypeError("format_dt expects a datetime object")
    # Convert to UTC if tz-aware, otherwise treat as UTC
    offset = dt.utcoffset()
    if offset is not None:
        # Subtract offset to get UTC time
        utc_dt = dt - offset
    else:
        utc_dt = dt
    # Return ISO 8601 format with trailing Z
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Regular expression to match URLs starting with http://, https://, ftp://, or www.
    url_re = re.compile(r'\b((?:https?://|ftp://|www\.)[^\s<>]+)', re.IGNORECASE)

    # Regular expression to match simple file paths (ending in common extensions).
    file_re = re.compile(r'\b([\w\/.-]+\.(?:py|txt|md|ipynb|html?|css|js))\b')

    def _make_link(url, display_text):
        """Return an HTML link element with target="_blank" and noopener."""
        return f'<a target="_blank" rel="noopener" href="{url}">{display_text}</a>'

    def _replace_url(match):
        raw_url = match.group(1)
        # If the URL does not start with a scheme, prepend http://
        if not re.match(r'^[a-z][a-z0-9+.-]*://', raw_url, re.IGNORECASE):
            href = 'http://' + raw_url
        else:
            href = raw_url
        return _make_link(href, raw_url)

    def _replace_file(match):
        path = match.group(1)
        href = f'/browse/{path}'
        return _make_link(href, path)

    # First replace actual URLs
    result = url_re.sub(_replace_url, text)

    # Then replace detected file references
    result = file_re.sub(_replace_file, result)

    return result

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, _, _, _ = urlparse.urlsplit(url)
    if scheme not in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = Urllib2HeadRequest(url, headers={'Host': netloc})
    try:
        resp = urlopen(req)
        try:
            if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
                return None
            return resp.info().get('content-type')
        finally:
            resp.close()
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    tag = tag.strip()
    if not tag:
        return False
    # Accept letters, digits, underscores, and hyphens
    import re
    pattern = r'^[A-Za-z0-9_\-]+$'
    return bool(re.match(pattern, tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion – child nodes are not recursively processed
    (i.e. the returned values are the immediate child elements themselves).
    If multiple children share the same tag, the corresponding value will be a
    list of elements in the order they appear.

    :param node: xml.etree.ElementTree.Element or similar node
    :return: dict mapping tag name to Element or list of Elements
    """
    result = {}
    for child in node:
        # strip namespace if present
        tag = child.tag
        if '}' in tag:
            tag = tag.split('}', 1)[1]
        if tag in result:
            existing = result[tag]
            if not isinstance(existing, list):
                result[tag] = [existing]
            result[tag].append(child)
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("url must be provided")
    # Normalize base URL (remove trailing slash)
    base = url.rstrip('/')
    # Determine the link path
    if document_path:
        # Ensure the path starts with a slash and does not include a preceding slash on base
        path = document_path
        if not path.startswith('/'):
            path = '/' + path
    else:
        path = '/.well-known/nodeinfo'
    # Build absolute href
    href = base + path
    # Construct the well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result: Dict[str, str] = {}
    try:
        data = json.loads(document)
    except Exception:
        # Try to parse as XRD (XML)
        try:
            root = ET.fromstring(document)
        except Exception:
            return result
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject = root.find("xrd:Subject", ns)
        if subject is not None:
            result["subject"] = subject.text or ""
        for link in root.findall("xrd:Link", ns):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                if rel == "self":
                    result["self"] = href
                elif rel == "http://webfinger.net/rel/hcard":
                    result["hcard_url"] = href
                else:
                    result[rel] = href
        return result

    # JSON format
    if "subject" in data:
        result["subject"] = data["subject"]
    for entry in data.get("links", []):
        rel = entry.get("rel")
        href = entry.get("href")
        if not rel or not href:
            continue
        if rel == "self":
            result["self"] = href
        elif rel == "http://webfinger.net/rel/hcard":
            result["hcard_url"] = href
        else:
            result[rel] = href
    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        _, host = handle.split("@", 1)
    except Exception:
        return None
    try:
        import urllib
        import urllib2
        url = f"https://{host}/.well-known/webfinger?resource=acct:{urllib.quote(handle)}"
        with urllib2.urlopen(url, timeout=10) as response:
            return response.read()
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

