@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, 'r') as f:
                data = yaml.safe_load(f)
        except Exception as e:
            raise IRValidatorException(f"Error loading YAML file {yaml_file}: {e}")

        if data is None or not isinstance(data, dict):
            raise IRValidatorException(
                f"YAML file {yaml_file} does not contain a mapping at the top level"
            )

        missing = []
        # List of mandatory fields that must be present in the YAML data.
        # This can be overridden by subclasses or set at runtime.
        mandatory_fields = getattr(cls, "required_fields", [])

        for field in mandatory_fields:
            if field not in data:
                missing.append(field)

        if missing:
            raise IRValidatorException(
                f"Mandatory fields missing in {yaml_file}: {', '.join(missing)}"
            )

        return data

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Base case: bail if not a dict
        if not isinstance(parser_dict, dict):
            return parser_dict
        # Resolve any top-level include directives
        while True:
            includes = parser_dict.pop('include', None)
            if not includes:
                break
            # Normalize to a list for uniform processing
            if not isinstance(includes, (list, tuple)):
                includes = [includes]
            for inc in includes:
                # If include is already a dict we can merge it directly
                if isinstance(inc, dict):
                    included = self._include_groups(inc)
                else:
                    # Otherwise we assume it is a path to a spec file.
                    # The method `self._load_config` is expected to
                    # load that file into a dictionary.
                    included = self._load_config(inc)
                    included = self._include_groups(included)
                parser_dict.update(included)
        # Recursively resolve any nested include directives
        for key, val in list(parser_dict.items()):
            if isinstance(val, dict):
                parser_dict[key] = self._include_groups(val)
        return parser_dict

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources. """
        defaults = {}
        for arg in self.args:
            if not isinstance(arg, _BaseOpt):
                continue

            # Attempt to fetch the value from the spec.
            val = getattr(self.spec, arg.name, None)
            if val is not None:
                defaults[arg.name] = val
            else:
                # Fallback to the argument's default if defined.
                if not isinstance(arg.default, NoDefault):
                    defaults[arg.name] = arg.default

            # If the argument is a dictionary option with a nested scheme,
            # recursively gather defaults from that scheme.
            if isinstance(arg, DictOption) and arg.scheme:
                child_defaults = arg.scheme.get_spec_defaults()
                if child_defaults:
                    defaults[arg.name] = child_defaults
        return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {
        # 'old_arg_name': 'new_arg_name',
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import warnings
    deprecation_map = getattr(self, 'deprecated_arg_names', {})
    for source, args_dict in (('CLI', cli_args), ('answer file', answer_file_args)):
        for arg, _ in args_dict.items():
            if arg in deprecation_map:
                new_name = deprecation_map[arg]
                warnings.warn(
                    f"Argument '{arg}' from {source} is deprecated; use '{new_name}' instead.",
                    DeprecationWarning,
                    stacklevel=2
                )

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Prefer a dedicated accessor on the parser if available
    if hasattr(self._parser, "get_option_spec"):
        return self._parser.get_option_spec(command_name, argument_name)

    # Try a common nested mapping structure:
    # self._parser.commands[command_name].options[argument_name]
    try:
        return self._parser.commands[command_name].options[argument_name]
    except Exception:
        pass

    # Fallback: look for command and argument in flat dicts that may exist
    try:
        return self._parser.commands[command_name][argument_name]
    except Exception:
        pass

    try:
        return self._parser.options[command_name][argument_name]
    except Exception:
        pass

    # As a last resort, scan all commands for the requested spec
    if hasattr(self._parser, "commands"):
        for cmd, spec in self._parser.commands.items():
            if cmd == command_name:
                if hasattr(spec, "options") and argument_name in spec.options:
                    return spec.options[argument_name]
                if isinstance(spec, dict) and argument_name in spec:
                    return spec[argument_name]

    # If nothing found, return None
    return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if args is None:
        return []
    # Accept dict or argparse.Namespace
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = vars(args).items()
        except Exception:
            return []
    return [name for name, value in items if value is None]

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Determine where to fetch required argument names
    required_args = getattr(self, 'required_args', None)
    if required_args is None:
        # Try common attribute names
        required_args = getattr(self, 'required_params', [])
    if not required_args:
        # Nothing to validate
        return

    # Normalize args to a mapping
    if isinstance(args, dict):
        arg_map = args
    else:
        # Assume argparse.Namespace or similar
        arg_map = {k: getattr(args, k, None) for k in required_args}

    missing = []
    for name in required_args:
        val = arg_map.get(name)
        if val is None:
            missing.append(name)

    if missing:
        missing_str = ', '.join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        conditional_args = []

        for opt in options_spec:
            req_when = opt.get('required_when')
            if not req_when:
                continue

            # Determine if the condition is a callable or a mapping
            condition_met = False

            if callable(req_when):
                try:
                    condition_met = bool(req_when(command_name, args))
                except Exception:
                    # If a callable fails, treat it as not met
                    condition_met = False
            elif isinstance(req_when, dict):
                condition_met = True
                for key, value in req_when.items():
                    if key == 'command':
                        # Allow value to be single command or iterable of commands
                        cmds = value if isinstance(value, (list, tuple, set)) else [value]
                        if command_name not in cmds:
                            condition_met = False
                            break
                    else:
                        # Check that the argument matches the expected value
                        if args.get(key) != value:
                            condition_met = False
                            break
            else:
                # Unsupported condition type; treat as not met
                condition_met = False

            if condition_met:
                name = opt.get('name')
                if name:
                    conditional_args.append(name)

        return conditional_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for name, value in args.items():
        if value is None:
            continue
        # Fetch the expected maximum length from the spec, if any
        arg_spec = self.parsed_yaml.get('args', {}).get(name, {})
        max_len = arg_spec.get('len')
        if max_len is None:
            continue
        if not isinstance(max_len, int):
            raise TypeError(f"Length for argument '{name}' must be an integer, got {type(max_len).__name__}")
        # Only objects that have a length are validated
        if hasattr(value, "__len__"):
            val_len = len(value)
            if val_len > max_len:
                raise ValueError(f"Argument '{name}' length {val_len} exceeds maximum allowed {max_len}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # self.choices is expected to be a mapping of argument names to iterable of allowed values
    choices_mapping = getattr(self, "choices", {})
    for arg_name, arg_value in args.items():
        if arg_name in choices_mapping:
            allowed = choices_mapping[arg_name]
            # Ensure allowed is iterable; skip if not
            if not hasattr(allowed, "__contains__"):
                continue
            if arg_value not in allowed:
                # Provide a clear error message indicating the issue
                allowed_formatted = ", ".join(repr(v) for v in allowed)
                raise ValueError(
                    f"Invalid value for argument {arg_name!r}: {repr(arg_value)} "
                    f"not in allowed selections: {allowed_formatted}"
                )
    # No return value; function raises on error or completes silently if all values are valid.

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # If no min or max defined, nothing to validate
    if not hasattr(self, 'min') and not hasattr(self, 'max'):
        return args

    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)

    # Support both sequence and mapping
    if isinstance(args, dict):
        items = args.items()
    else:
        items = enumerate(args)

    for name, val in items:
        if val is None:  # skip unset values
            continue
        if min_val is not None and val < min_val:
            raise ValueError(f"Argument {name}={val} is less than minimum {min_val}")
        if max_val is not None and val > max_val:
            raise ValueError(f"Argument {name}={val} is greater than maximum {max_val}")

    return args

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json

    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_path):
        return {}

    with open(spec_path, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    def _flatten(d, parent_key=''):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = str(self.config_path)
